@keyframes logoReveal {
  from { opacity: 0; letter-spacing: 0.5em; filter: blur(8px); }
  to { opacity: 1; letter-spacing: 0.04em; filter: blur(0); }
}
@keyframes studioFadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}
@keyframes fadeInUpHero {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: translateY(0); }
}
@keyframes statsEntrance {
  from { opacity: 0; transform: scale(0.96); }
  to { opacity: 1; transform: scale(1); }
}

.anim-logo { animation: logoReveal 1.5s ease-out both; }
.anim-sub-hero { animation: fadeInUpHero 1s ease-out 0.4s both; }
.anim-stats { animation: statsEntrance 0.8s ease-out 0.7s both; }

